/* بيانات باب krb: تُحمَّل عند أول فتح للقسم */
window.KRB = {"ch":[{"id":"inzar","t":"إنظار المعسر والتيسير","d":"الآيات التي أمرت بإمهال المدين المعسر إلى ميسرة وندبت إلى التصدق عليه، وبشّرت بأن مع العسر يسراً، وبيّنت أن الله لا يكلّف نفساً إلا وسعها، وأرشدت إلى توثيق الدين بالكتابة."},{"id":"riqab","t":"فك الرقاب والكفارات","d":"الآيات التي ذكرت فك الرقبة وعدّته اقتحاماً للعقبة، وجعلت الرقاب مصرفاً من مصارف الصدقات، وأمرت بمكاتبة من طلب الكتابة وإعانته، وأوجبت تحرير الرقبة في بعض الكفارات."},{"id":"shidda","t":"الغارمون والإنفاق وقت الحاجة","d":"الآيات التي ذكرت الغارمين في مصارف الصدقات، والإطعام في يوم ذي مسغبة، والإنفاق من العفو، والحضّ على طعام المسكين."},{"id":"ibtila","t":"الابتلاء والصبر وإحياء الرجاء","d":"الآيات التي أخبرت بابتلاء المؤمنين بالخوف والجوع ونقص الأموال والأنفس، وسنّة الله في الامتحان قبل النصر، والنهي عن اليأس والقنوط، والتواصي بالصبر والمرحمة."},{"id":"takaful","t":"الأخوّة والتكافل وستر المؤمنين","d":"الآيات التي جعلت المؤمنين إخوة، وحثّت على الشفاعة الحسنة والتعاون، وعقدت ولاية النصرة بين المؤمنين، وصانت أعراضهم من إشاعة الفاحشة والغيبة."}],"tp":[{"id":"nazira","ch":"inzar","t":"«وإن كان ذو عسرة فنظرة إلى ميسرة»","e":"الأمر بإنظار المدين المعسر إلى ميسرة.","ay":[[2,280,280]],"q":[{"bk":"saadi","s":2,"ay":280,"x":"أي: وإن كان الذي عليه الدَّين معسراً لا يقدر على الوفاء وجب على غريمه أن يُنْظِره إلى ميسرة، وهو يجب عليه إذا حصل له وفاء بأي طريق مباح أن يوفي ما عليه، وإن تصدق عليه غريمه بإسقاط الدَّينِ كلِّه أو بعضه فهو خير له، ويهون على العبد التزام الأمور الشرعية واجتناب المعاملات الربوية والإحسان إلى المعسرين؛ عِلْمُه بأن له يوماً يرجع فيه إلى الله ويوفيه عمله ولا يظلمه مثقال ذرة.","w":"السعدي","en":"That is: if the one who owes the debt is in hardship, unable to pay, it is obligatory for his creditor to give him time until ease; and when he obtains the means to pay by any lawful way, it is obligatory for him to pay what he owes. If his creditor gives charity to him by waiving the debt, all or part of it, that is better for him. What makes it easy for a servant to keep to the matters of the Law, to avoid usurious dealings and to be kind to those in hardship is his knowledge that he has a day on which he returns to Allah, who will repay him his deeds and will not wrong him by the weight of an atom."}],"h":["tajir"]},{"id":"tasaddaq","ch":"inzar","t":"«وأن تصدقوا خير لكم»: التصدق على المعسر","e":"الندب إلى التصدق على المعسر بإسقاط الدين كله أو بعضه.","ay":[[2,280,280]],"q":[{"bk":"ibnkathir","s":2,"ay":280,"x":"وَقَوْلُهُ: ﴿وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ وَأَنْ تَصَدَّقُوا خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ﴾ : يَأْمُرُ تَعَالَى بِالصَّبْرِ عَلَى الْمُعْسِرِ الَّذِي لَا يَجِدُ وَفَاءً، فَقَالَ: ﴿وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَة﴾ [أَيْ] : لَا كَمَا كَانَ أَهْلُ الْجَاهِلِيَّةِ يَقُولُ أَحَدُهُمْ لِمَدِينِهِ إِذَا حَلَّ عَلَيْهِ الدَّيْنُ: إِمَّا أَنْ تَقْضِيَ وَإِمَّا أَنْ تُرْبِيَ. ثُمَّ يَنْدُبُ إِلَى الْوَضْعِ عَنْهُ، وَيَعِدُ عَلَى ذَلِكَ الْخَيْرَ وَالثَّوَابَ الْجَزِيلَ، فَقَالَ: ﴿وَأَنْ تَصَدَّقُوا خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ﴾ أَيْ: وَأَنْ تَتْرُكُوا رَأْسَ الْمَالِ بِالْكُلِّيَّةِ وَتَضَعُوهُ عَنِ الْمَدِينِ.","w":"ابن كثير","en":"His words: [\"And if the debtor is in hardship, then let there be postponement until ease. But that you remit it as charity is better for you, if you only knew\"]. Allah commands patience with the one in hardship who finds nothing with which to pay, so He said: [\"And if the debtor is in hardship, then let there be postponement until ease\"] — not as the people of the Jahiliyya used to do, when one of them would say to his debtor when the debt fell due: either you pay or you add interest. Then He encourages remitting from him and promises abundant good and reward for it, so He said: [\"But that you remit it as charity is better for you, if you only knew\"], that is, that you leave the principal altogether and remit it from the debtor."}],"h":["sarra"]},{"id":"yusr","ch":"inzar","t":"«سيجعل الله بعد عسر يسراً» و«إن مع العسر يسراً»","e":"البشارة بأن الله يجعل بعد العسر يسراً، وأن مع العسر يسراً.","ay":[[65,7,7],[94,5,6]],"q":[{"bk":"saadi","s":65,"ay":7,"x":"وهذا مناسبٌ للحكمة والرحمة الإلهية؛ حيث جعل كلاًّ بحسبه، وخفَّف عن المعسر، وأنَّه لا يكلِّفه إلاَّ ما آتاه؛ فلا يكلِّف الله نفساً إلا وسعها في باب النفقة وغيرها، {سيجعلُ الله بعد عسرٍ يُسۡراً}: وهذه بشارةٌ للمعسرين أنَّ الله تعالى سيزيلُ عنهم الشدَّة ويرفع عنهم المشقَّة؛ فإنَّ مع العسر يسراً، إنَّ مع العسر يسراً.","w":"السعدي","en":"This accords with Allah's wisdom and mercy: He made each according to his means and lightened the burden of the one in hardship, and He burdens him only with what He has given him. So Allah does not burden a soul beyond its capacity in the matter of spending and other things. [\"Allah will bring about, after hardship, ease\"] — this is glad tidings for those in hardship that Allah will remove the distress from them and lift the difficulty from them, for with hardship is ease, with hardship is ease."},{"bk":"saadi","s":94,"ay":5,"x":"{إنَّ مع العُسۡرِ يُسۡراً}: بشارةٌ عظيمةٌ أنَّه كلَّما وُجِدَ عسرٌ وصعوبةٌ؛ فإنَّ اليسر يقارنه ويصاحبه، حتى لو دخل العسر جحر ضبٍّ؛ لدخل عليه اليسر فأخرجه؛ كما قال تعالى:{سيجعل اللهُ بعدَ عُسۡرٍ يُسۡراً}، وكما قال النبيُّ - صلى الله عليه وسلم -: «وإنَّ الفرج مع الكرب، وإنَّ مع العسر يسراً ». وتعريف العسر في الآيتين يدلُّ على أنَّه واحدٌ، وتنكير اليسرِ يدلُّ على تكراره؛ فلن يغلب عسرٌ يسرين. وفي تعريفه بالألف واللاَّم الدالِّ على الاستغراق والعموم يدل على أنَّ كلَّ عسرٍ وإنْ بلغ من الصعوبة ما بلغ؛ فإنَّه في آخره التيسير ملازمٌ له.","w":"السعدي","en":"Glad tidings of great weight: whenever hardship and difficulty occur, ease accompanies it and goes with it, so that were hardship to enter the hole of a lizard, ease would enter after it and bring it out; as Allah said: [\"Allah will bring about, after hardship, ease\"], and as the Prophet, may Allah bless him and grant him peace, said: \"Relief comes with distress, and with hardship is ease.\" The definite article on hardship in the two verses shows it is one, and the indefinite form of ease shows it recurs; so one hardship will never overcome two eases. And the definite article, which indicates inclusion and generality, shows that every hardship, however severe, has ease following at its end, bound to it."}],"h":["yassara"]},{"id":"wus","ch":"inzar","t":"«لا يكلف الله نفساً إلا وسعها»: التيسير ورفع الحرج","e":"أن الله لا يكلّف نفساً إلا وسعها، وإرادته اليسر بعباده.","ay":[[2,286,286],[2,185,185]],"q":[{"bk":"saadi","s":2,"ay":286,"x":"ويؤخذ من هذا قاعدة التيسير ونفي الحرج في أمور الدين كلها، وقاعدة العفو عن النسيان والخطأ في العبادات وفي حقوق الله تعالى، وكذلك في حقوق الخلق من جهة رفع المأثم وتوجيه الذم، وأما وجوب ضمان المتلفات خطأً أو نسياناً في النفوس والأموال فإنه مرتب على الإتلاف بغير حق، وذلك شامل لحالة الخطأ والنسيان والعمد.","w":"السعدي","en":"From this is taken the rule of ease and the removal of hardship in all matters of religion, and the rule of pardon for forgetfulness and error in acts of worship and in the rights of Allah, and likewise in the rights of creatures as regards lifting sin and blame. As for the obligation to make good what is destroyed by error or forgetfulness in lives and property, it follows from destroying without right, and that covers error, forgetfulness and intent alike."},{"bk":"saadi","s":2,"ay":185,"x":"أي: يريد الله تعالى أن ييسر عليكم الطرق الموصلة إلى رضوانه أعظم تيسير ويسهلها أبلغ تسهيل، ولهذا كان جميع ما أمر الله به عباده في غاية السهولة في أصله، وإذا حصلت بعض العوارض الموجبة لثقله؛ سهله تسهيلاً آخر إما بإسقاطه أو تخفيفه بأنواع التخفيفات، وهذه جملة لا يمكن تفصيلها، لأن تفاصيلها جميع الشرعيات، ويدخل فيها جميع الرخص والتخفيفات.","w":"السعدي","en":"That is: Allah intends to make easy for you the paths that lead to His good pleasure with the greatest ease, and to smooth them with the most complete smoothing. For that reason everything that Allah commanded His servants is, in its origin, extremely easy; and when some circumstances arise that make it heavy, He eases it a second time, either by dropping it or by lightening it in various ways. This is a statement that cannot be set out in detail, because its details are all the rulings of the Law, and it includes all the concessions and lightenings."}],"h":[]},{"id":"dayn","ch":"inzar","t":"«إذا تداينتم بدين إلى أجل مسمى فاكتبوه»","e":"الأمر بكتابة الدين إذا كان إلى أجل مسمى لحفظ الحقوق.","ay":[[2,282,282]],"q":[{"bk":"saadi","s":2,"ay":282,"x":"ومنها: أمره تعالى بكتابة الديون، وهذا الأمر قد يجب إذا وجب حفظ الحق كالذي للعبد عليه ولاية، كأموال اليتامى والأوقاف والوكلاء والأمناء، وقد يقارب الوجوب كما إذا كان الحق متمحضاً للعبد فقد يقوى الوجوب وقد يقوى الاستحباب، بحسب الأحوال المقتضية لذلك، وعلى كل حال فالكتابة من أعظم ما تحفظ به هذه المعاملات المؤجلة لكثرة النسيان ولوقوع المغالطات، وللاحتراز من الخونة الذين لا يخشون الله تعالى.","w":"السعدي","en":"Among them: His command to write down debts. This command may be obligatory when preserving the right is obligatory, such as the right of one over whom the servant has guardianship, like the property of orphans, endowments, agents and trustees; and it may come close to obligation, as when the right belongs purely to the servant, where the obligation may be strong or the recommendation may be strong, according to the circumstances. In every case writing is among the greatest means of protecting these deferred transactions, given how much people forget and how often mistakes arise, and as a precaution against the treacherous who do not fear Allah the Exalted."},{"bk":"saadi","s":2,"ay":282,"x":"ومنها: أن الكتابة بين المتعاملين من أفضل الأعمال ومن الإحسان إليهما، وفيها حفظ حقوقهما وبراءة ذممهما كما أمره الله بذلك فليحتسب الكاتب بين الناس هذه الأمور ليحظى بثوابها.","w":"السعدي","en":"Among them: that writing between the two parties is among the best of deeds and a kindness to both, protecting their rights and freeing their obligations, as Allah commanded him. So let the scribe seek reward for these matters among people, that he may gain their recompense."}],"h":["akhdh"]},{"id":"aqaba","ch":"riqab","t":"«فلا اقتحم العقبة... فك رقبة»","e":"عدّ فك الرقبة والإطعام في يوم ذي مسغبة اقتحاماً للعقبة.","ay":[[90,11,16]],"q":[{"bk":"saadi","s":90,"ay":13,"x":"ثم فسَّر هذه العقبة بقوله: {فكُّ رقبةٍ}؛ أي: فكُّها من الرقِّ بعتقها أو مساعدتها على أداء كتابتها، ومن باب أولى فكاك الأسير المسلم عند الكفار، {أو إطعامٌ في يوم ذي مَسۡغَبَةٍ}؛ أي: مجاعةٍ شديدةٍ؛ بأن يطعم وقت الحاجة أشدَّ الناس حاجةً، {يتيماً ذا مَقۡرَبَةٍ}؛ أي: جامعاً بين كونه يتيماً وفقيراً ذا قرابة، {أو مسكيناً ذا مَتۡرَبَةٍ}؛ أي: قد لزق بالتراب من الحاجة والضَّرورة.","w":"السعدي","en":"Then He explained this steep path by His words: [\"Freeing a neck\"], that is, freeing it from bondage by emancipating it or helping it to pay for its writ of emancipation, and all the more ransoming a Muslim captive among the disbelievers; [\"or feeding on a day of severe hunger\"], that is, famine, by feeding at the time of need those who are in the greatest need; [\"an orphan of near kinship\"], that is, one who combines being an orphan and poor with being a relative; [\"or a needy person in the dust\"], that is, one who clings to the dust from need and necessity."}],"h":["itq"]},{"id":"riqab9","ch":"riqab","t":"«وفي الرقاب»: الرقاب في مصارف الصدقات","e":"ذكر «الرقاب» مصرفاً من مصارف الصدقات، ودخول العتق وفداء الأسرى فيه.","ay":[[9,60,60],[2,177,177]],"q":[{"bk":"saadi","s":9,"ay":60,"x":"وفكُّ الرقبة المسلمة التي في حبس الكفار داخلٌ في هذا، بل أولى. ويدخل في هذا أنَّه يجوز أن يعتق [منها] الرقاب استقلالاً؛ لدخوله في قوله:{وفي الرِّقاب}.","w":"السعدي","en":"Ransoming a Muslim neck held in captivity by the disbelievers is included in this, and even more so. It also includes that necks may be emancipated outright from it, because it falls under His words [\"and for freeing necks\"]."},{"bk":"saadi","s":2,"ay":177,"x":"فيدخل فيه العتق والإعانة عليه وبذل مال للمكاتَب ليوفي سيده وفداء الأسراء عند الكفار أو عند الظلمة.","w":"السعدي","en":"It includes emancipation and helping toward it, giving wealth to the one under a writ of emancipation so that he can pay his master, and ransoming captives held by the disbelievers or by oppressors."}],"h":[]},{"id":"mukataba","ch":"riqab","t":"«والذين يبتغون الكتاب مما ملكت أيمانكم فكاتبوهم»","e":"الأمر بمكاتبة من طلب الكتابة وإيتائه من مال الله.","ay":[[24,33,33]],"q":[{"bk":"saadi","s":24,"ay":33,"x":"وقوله:{والذين يبتغونَ الكتاب مما مَلَكَتۡ أيمانكُم فكاتِبوهم إن علمتُم فيهم خيراً}؛ أي: من ابتغى وطلب منكم الكتابةَ وأن يَشْتَرِي نفسَه من عبيدٍ وإماءٍ؛ فأجيبوه إلى ما طلب، وكاتبوه، {إنۡ علمتُم فيهم}؛ أي: في الطالبين للكتابة {خيراً}؛ أي: قدرة على التكسُّب وصلاحاً في دينه؛ لأنَّ في الكتابة تحصيلَ المصلحتين: مصلحة العِتْق والحريَّة، ومصلحة العوض الذي يبذُلُه في فداء نفسه، وربما جدَّ واجتهد وأدرك لسيِّده في مدَّة الكتابة من المال ما لا يحصُلُ في رقِّه، فلا يكون ضررٌ على السيِّد في كتابتِهِ، مع حصول عظيم المنفعة للعبد؛ فلذلك أمر الله بالكتابة على هذا الوجه أمرَ إيجابٍ؛ كما هو الظاهر، أو أمر استحبابٍ على القول الآخر، وأمر بمعاوَنَتِهِم على كتابَتِهِم؛ لكونهم محتاجين لذلك؛ بسبب أنَّهم لا مال لهم، فقال …","w":"السعدي","en":"His words: [\"And those who seek a writ of emancipation from among whom your right hands possess, then write it for them if you know in them any good\"], that is, whoever of the male and female slaves seeks and asks of you a writ and to buy himself, then respond to what he asks and contract with him; [\"if you know in them\"], that is, in those who ask for the writ, [\"any good\"], that is, ability to earn and soundness in his religion; for in the writ is the achievement of two benefits: the benefit of emancipation and freedom, and the benefit of the payment he gives in ransoming himself. Perhaps he strives and works hard and earns for his master during the term of the writ more wealth than he could earn in bondage, so there is no harm to the master in writing it, with great benefit for the slave. That is why Allah commanded the writ in this way, as a command of obligation as is apparent, or a command of recommendation on the other view, and He commanded that they be helped in their writ because they need it, since they have no wealth, so He said …"}],"h":[]},{"id":"kaffara","ch":"riqab","t":"تحرير الرقبة في الكفارات","e":"ورود تحرير الرقبة في كفارة القتل الخطأ والظهار واليمين.","ay":[[4,92,92],[58,3,4],[5,89,89]],"q":[{"bk":"saadi","s":4,"ay":92,"x":"ومن علمه وحكمته أن أوجب على القاتل كفارةً مناسبةً لما صدر منه؛ فإنَّه تسبَّب لإعدام نفس محترمة، وأخرجها من الوجود إلى العدم، فناسب أن يَعْتِقَ رقبةً ويخرِجَها من رِقِّ العبوديَّة للخلق إلى الحريَّة التامَّة؛ فإنْ لم يجد هذه الرقبة؛ صام شهرين متتابعين، فأخرج نفسه من رقِّ الشهوات واللَّذَّات الحسيَّة القاطعة للعبد عن سعادتِهِ الأبديَّة إلى التعبُّد لله تعالى بتركها تقرباً إلى الله، ومدَّها تعالى بهذه المدة الكثيرة الشاقَّة في عددها ووجوب التتابُع فيها، ولم يشرع الإطعام في هذه المواضع لعدم المناسبة؛ بخلاف الظِّهار؛ كما سيأتي إن شاء الله تعالى.","w":"السعدي","en":"Part of His knowledge and wisdom is that He made obligatory on the killer an expiation fitting what he did. He was the cause of destroying a sacred life and bringing it from existence into non-existence, so it fits that he free a neck and bring it out of the bondage of servitude to creatures into complete freedom. If he does not find this neck, he fasts two consecutive months, thereby bringing himself out of bondage to desires and sensual pleasures that cut the servant off from his everlasting happiness, into worship of Allah the Exalted by leaving them in nearness to Him. He prolonged it by this long period, hard in its number and in the obligation of continuity; and He did not prescribe feeding in these cases because it does not fit, unlike zihar, as will come, if Allah wills."},{"bk":"saadi","s":58,"ay":3,"x":"ومنها: أنَّه يجزئ في كفارة الرَّقبة الصغير والكبير والذَّكر والأنثى؛ لإطلاق الآية في ذلك.","w":"السعدي","en":"Among them: that it is sufficient in the expiation of a neck whether young or old, male or female, since the verse is unrestricted in that."}],"h":[]},{"id":"gharimun","ch":"shidda","t":"«والغارمين»: الغارمون في مصارف الصدقات","e":"ذكر «الغارمين» مصرفاً من مصارف الصدقات وبيان قسميهم.","ay":[[9,60,60]],"q":[{"bk":"saadi","s":9,"ay":60,"x":"السادس: الغارمون، وهم قسمان: أحدهما: الغارمون لإصلاح ذات البين، وهو أن يكون بين طائفتين من الناس شرٌّ وفتنةٌ، فيتوسط الرجل للإصلاح بينهم بمال يبذُلُه لأحدهم أو لهم كلّهم، فُجِعلَ له نصيبٌ من الزكاة؛ ليكون أنشط له وأقوى لعزمِهِ، فيُعْطى ولو كان غنيًّا. والثاني: من غَرِمَ لنفسه ثم أعسر؛ فإنَّه يُعطى ما يُوفي به دينَه.","w":"السعدي","en":"The sixth: those in debt, and they are two kinds. The first: those in debt for reconciliation between people, which is when there is evil and discord between two groups and a man steps in to reconcile them with money he gives to one of them or to all of them; so he is given a share of zakat to make him more energetic and firmer in resolve, and he is given even if he is rich. The second: one who incurred debt for himself and then fell into hardship; he is given what he can pay his debt with."}],"h":["awla"]},{"id":"masghaba","ch":"shidda","t":"«أو إطعام في يوم ذي مسغبة يتيماً ذا مقربة أو مسكيناً ذا متربة»","e":"الإطعام في يوم ذي مسغبة يتيماً ذا مقربة أو مسكيناً ذا متربة.","ay":[[90,14,16]],"q":[{"bk":"ibnkathir","s":90,"ay":14,"x":"وَقَوْلُهُ: ﴿أَوْ إِطْعَامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ﴾ قَالَ ابْنُ عَبَّاسٍ: ذِي مَجَاعَةٍ. وَكَذَا قَالَ عِكْرِمَةُ، وَمُجَاهِدٌ، وَالضَّحَّاكُ، وَقَتَادَةُ، وَغَيْرُ وَاحِدٍ. والسَّغَب: هُوَ الْجُوعُ.","w":"ابن كثير","en":"His words: [\"Or feeding on a day of severe hunger\"]. Ibn Abbas said: of famine. So said Ikrima, Mujahid, al-Dahhak, Qatada and more than one. And al-saghab is hunger."}],"h":[]},{"id":"afw","ch":"shidda","t":"«ويسألونك ماذا ينفقون قل العفو»","e":"الأمر بإنفاق «العفو» وهو ما تيسّر من المال.","ay":[[2,219,219]],"q":[{"bk":"saadi","s":2,"ay":219,"x":"وهذا سؤال عن مقدار ما ينفقونه من أموالهم، فيسر الله لهم الأمر وأمرهم أن ينفقوا العفو، وهو المتيسر من أموالهم الذي لا تتعلق به حاجتهم وضرورتهم، وهذا يرجع إلى كل أحد بحسبه من غني وفقير ومتوسط، كل له قدرة على إنفاق ما عفا من ماله ولو شق تمرة، ولهذا أمر الله رسوله - صلى الله عليه وسلم -، أن يأخذ العفو من أخلاق الناس وصدقاتهم، ولا يكلفهم ما يشق عليهم؛ ذلك بأن الله تعالى لم يأمرنا بما أمرنا به حاجة منه لنا أو تكليفاً لنا بما يشق، بل أمرنا بما فيه سعادتنا وما يسهل علينا وما به النفع لنا ولإخواننا فيستحق على ذلك أتم الحمد. ولما بين تعالى هذا البيان الشافي وأطلع العباد على أسرار شرعه قال …","w":"السعدي","en":"This was a question about the amount they should spend of their wealth, so Allah made the matter easy for them and commanded them to spend \"the surplus\", which is what is easily spared of their wealth and on which their need and necessity do not depend. This differs for each person according to his means, whether rich, poor or in between; each has the ability to spend what he can spare of his wealth, even half a date. That is why Allah commanded His Messenger, may Allah bless him and grant him peace, to take the surplus of people's character and their charity, and not burden them with what is hard for them. That is because Allah the Exalted did not command us what He commanded out of any need of ours for Him or to burden us with hardship, but commanded us what contains our happiness, what is easy for us and what benefits us and our brothers; so He deserves the fullest praise for that. When He had given this complete clarification and informed His servants of the secrets of His law, He said …"}],"h":[]},{"id":"miskin","ch":"shidda","t":"«ولا يحض على طعام المسكين»","e":"ذمّ من لا يحضّ على طعام المسكين وما يتصل بذلك من بذل المعروف.","ay":[[107,1,3],[69,33,34]],"q":[{"bk":"saadi","s":107,"ay":3,"x":"{ولا يحضُّ}: غيره {على طعام المسكينِ}: ومن باب أولى أنَّه بنفسه لا يطعم المسكين.","w":"السعدي","en":"[\"And does not urge the feeding of the needy\"]: that is, he does not urge others to it, and all the more he himself does not feed the needy."},{"bk":"saadi","s":107,"ay":3,"x":"وفي هذه السورة الحثُّ على إطعام اليتيم والمساكين، والتَّحضيض على ذلك، ومراعاة الصَّلاة، والمحافظة عليها، وعلى الإخلاص فيها، وفي سائر الأعمال ، والحثُّ على فعل المعروف، وبذل الأمور الخفيفة كعارية الإناء والدَّلو والكتاب ونحو ذلك؛ لأنَّ الله ذمَّ من لم يفعل ذلك.","w":"السعدي","en":"In this surah is the urging of feeding the orphan and the needy and encouraging it, the care for prayer and keeping to it and sincerity in it and in all deeds, and the urging of doing good and giving small useful things such as lending a vessel, a bucket, a book and the like, because Allah blamed the one who does not do that."}],"h":["saee"]},{"id":"ibtila","ch":"ibtila","t":"«ولنبلونكم بشيء من الخوف والجوع ونقص من الأموال»","e":"الإخبار بابتلاء المؤمنين بالخوف والجوع ونقص الأموال والأنفس وتبشير الصابرين.","ay":[[2,155,157]],"q":[{"bk":"saadi","s":2,"ay":155,"x":"أخبر تعالى أنه لا بد أن يبتليَ عباده بالمحن ليتبين الصادق من الكاذب والجازع من الصابر، وهذه سنته تعالى في عباده، لأن السراء لو استمرت لأهل الإيمان ولم يحصل معها محنة لحصل الاختلاط الذي هو فساد، وحكمة الله تقتضي تمييز أهل الخير من أهل الشر، هذه فائدة المحن لا إزالة ما مع المؤمنين من الإيمان ولا ردهم عن دينهم، فما كان الله ليضيع إيمان المؤمنين.","w":"السعدي","en":"Allah informed that He will certainly test His servants with trials, so that the truthful may be distinguished from the false and the impatient from the patient. This is His way with His servants, because if ease continued for the people of faith with no trial alongside it, mixing would occur, and that is corruption; and Allah's wisdom requires distinguishing the people of good from the people of evil. This is the benefit of trials, not removing the faith the believers have or turning them from their religion; for Allah would never let the faith of the believers be lost."},{"bk":"saadi","s":2,"ay":155,"x":"وأما من وفقه الله للصبر عند وجود هذه المصائب فحبس نفسه عن التسخط قولاً وفعلاً واحتسب أجرها عند الله وعلم أن ما يدركه من الأجر بصبره أعظم من المصيبة التي حصلت له، بل المصيبة تكون نعمة في حقه لأنها صارت طريقاً لحصول ما هو خير له وأنفع منها، فقد امتثل أمر الله وفاز بالثواب، فلهذا قال تعالى:{وبشر الصابرين}؛ أي: بشرهم بأنهم يوفون أجرهم بغير حساب، فالصابرون هم الذين فازوا بالبشارة العظيمة والمنحة الجسيمة، ثم وصفهم بقوله: {156}{الذين إذا أصابتهم مصيبة}؛ وهي كل ما يؤلم القلب أو البدن أو كليهما مما تقدم ذكره، {قالوا إنا لله}؛ أي: مملوكون لله مدبرون تحت أمره وتصريفه فليس لنا من أنفسنا وأموالنا شيء …","w":"السعدي","en":"As for the one whom Allah grants success in patience when these misfortunes come, he restrains himself from discontent in word and deed, seeks the reward with Allah, and knows that the reward he obtains by his patience is greater than the misfortune that befell him; indeed the misfortune becomes a blessing for him because it was a path to what is better and more beneficial for him. He has obeyed Allah's command and won the reward. So Allah said: [\"And give good tidings to the patient\"], that is, give them tidings that they will be paid their reward without account; the patient are those who attained the great glad tidings and the abundant gift. Then He described them: [\"Those who, when disaster strikes them\"], which is everything that pains the heart or the body or both, of what was mentioned before, [\"say: Indeed we belong to Allah\"], that is, we are owned by Allah, governed under His command and disposal, so we have nothing of ourselves or our wealth …"}],"h":["ajaba"]},{"id":"zalzala","ch":"ibtila","t":"«مستهم البأساء والضراء وزلزلوا حتى يقول الرسول والذين آمنوا معه متى نصر الله»","e":"بيان أن البأساء والضراء والزلزلة أصابت الأمم قبلنا قبل أن يأتي نصر الله.","ay":[[2,214,214]],"q":[{"bk":"saadi","s":2,"ay":214,"x":"يخبر تبارك وتعالى أنه لا بد أن يمتحن عباده بالسراء والضراء والمشقة كما فعل بمن قبلهم، فهي سنته الجارية التي لا تتغير ولا تتبدل، أن من قام بدينه وشرعه لا بد أن يبتليه، فإن صبر على أمر الله، ولم يبال بالمكاره الواقفة في سبيله، فهو الصادق الذي قد نال من السعادة كمالها ومن السيادة آلتها، ومن جعل فتنة الناس كعذاب الله، بأن صدته المكاره عما هو بصدده، وثنته المحن عن مقصده، فهو الكاذب في دعوى الإيمان، فإنه ليس الإيمان بالتحلي والتمني ومجرد الدعاوي؛ حتى تصدقه الأعمال أو تكذبه، فقد جرى على الأمم الأقدمين ما ذكر الله عنهم {مستهم البأساء والضراء}؛ أي: الفقر والأمراض في أبدانهم {وزلزلوا}؛ بأنواع المخاوف من التهديد بالقتل والنفي، وأخذ الأموال، وقتل الأحبة، وأنواع المضار …","w":"السعدي","en":"The Blessed and Exalted informs that He will certainly test His servants with ease and hardship and difficulty, as He did with those before them; this is His continuing way, which does not change or alter: whoever stands by His religion and law will surely be tried. If he is patient in Allah's command and heeds not the unpleasant things that stand in his way, he is the truthful one who has attained happiness in its fullness and leadership in its tools; but whoever makes people's persecution like Allah's punishment, so that unpleasant things turn him away from what he is engaged in and trials turn him from his goal, he is false in his claim of faith. For faith is not mere adornment, wishing and claims, until deeds confirm it or deny it. What Allah mentioned of the earlier nations passed over them: [\"Poverty and hardship touched them\"], that is, poverty and illnesses in their bodies, [\"and they were shaken\"] with kinds of fears, such as threats of killing and exile, seizure of property, the killing of loved ones and other kinds of harm …"},{"bk":"ibnkathir","s":2,"ay":214,"x":"﴿وَزُلْزِلُوا﴾ خَوْفًا مِنَ الْأَعْدَاءِ زلْزالا شَدِيدًا، وَامْتُحِنُوا امْتِحَانًا عَظِيمًا، كَمَا جَاءَ فِي الْحَدِيثِ الصَّحِيحِ عَنْ خَبَّاب بْنِ الأرَتّ قَالَ: قُلْنَا: يَا رَسُولَ اللَّهِ، أَلَا تَسْتَنْصِرُ لَنَا؟ أَلَا تَدْعُو اللَّهَ لَنَا؟ فَقَالَ: \"إِنَّ مَنْ كَانَ قَبْلَكُمْ كَانَ أَحَدُهُمْ يُوضَعُ الْمِنْشَارُ عَلَى مفْرَق رَأْسِهِ فَيَخْلُصُ إِلَى قَدَمَيْهِ، لَا يَصْرفه ذَلِكَ عَنْ دِينِهِ، ويُمْشَطُ بِأَمْشَاطِ الْحَدِيدِ مَا بَيْنَ لَحْمِهِ وَعَظْمِهِ، لَا يَصْرِفُهُ ذَلِكَ عَنْ دِينِهِ\".","w":"ابن كثير","en":"[\"And they were shaken\"] with fear of the enemies, a severe shaking, and they were tried with a great trial, as in the sound hadith from Khabbab ibn al-Aratt who said: We said, \"O Messenger of Allah, will you not ask for help for us? Will you not call upon Allah for us?\" He said: \"Among those before you, one of them would have a saw placed on the parting of his head and it would reach his feet, and that would not turn him from his religion; and he would be combed with iron combs between his flesh and his bone, and that would not turn him from his religion.\""}],"h":["karb"]},{"id":"maal","ch":"ibtila","t":"«لتبلون في أموالكم وأنفسكم»","e":"الإخبار بابتلاء المؤمنين في أموالهم وأنفسهم، والأمر بالصبر والتقوى.","ay":[[3,186,186]],"q":[{"bk":"saadi","s":3,"ay":186,"x":"يخبر تعالى ويخاطب المؤمنين أنهم سيبتلون في أموالهم من النفقات الواجبة والمستحبة ومن التعريض لإتلافها في سبيل الله وفي أنفسهم من التكليف بأعباء التكاليف الثقيلة على كثير من الناس كالجهاد في سبيل الله والتعرض فيه للتعب والقتل والأسر والجراح وكالأمراض التي تصيبه في نفسه أو فيمن يحب، ولتسمعن من الذين أوتوا الكتاب والمشركين {أذى كثيراً} من الطعن فيكم وفي دينكم وكتابكم ورسولكم.","w":"السعدي","en":"Allah informs and addresses the believers that they will be tested in their wealth, through obligatory and recommended spending and through exposing it to loss in the way of Allah, and in their selves, through the burden of heavy duties that are hard for many people such as striving in the way of Allah and the exposure in it to fatigue, killing, captivity and wounds, and such as illnesses that strike one in himself or in those he loves; and they will hear from those who were given the Book and from the polytheists \"much abuse\", insults against you, your religion, your Book and your Messenger."},{"bk":"saadi","s":3,"ay":186,"x":"ومنها: أنه تعالى يقدر عليهم هذه الأمور لما يريده بهم من الخير ليعلي درجاتهم ويكفر من سيئاتهم وليزداد بذلك إيمانهم ويتم به إيقانهم فإنه إذا أخبرهم بذلك ووقع كما أخبر، {قالوا هذا ما وعدنا الله ورسوله وصدق الله ورسوله وما زادهم إلا إيماناً وتسليماً}.","w":"السعدي","en":"Among them: that Allah decrees these things for them because of the good He intends for them, to raise their ranks, to expiate their evil deeds, and so that their faith increases and their certainty is completed; for when He informs them of this and it happens as He informed, [\"they said: This is what Allah and His Messenger promised us, and Allah and His Messenger spoke the truth, and it increased them only in faith and submission\"]."}],"h":[]},{"id":"yaas","ch":"ibtila","t":"«ولا تيأسوا من روح الله»، «لا تقنطوا من رحمة الله»","e":"النهي عن اليأس من روح الله والقنوط من رحمته.","ay":[[12,87,87],[39,53,53]],"q":[{"bk":"saadi","s":12,"ay":87,"x":"أي: قال يعقوب عليه السلام لبنيه: {يا بَنِيَّ اذهبوا فتحسَّسوا من يوسف وأخيه}؛ أي: احرصوا واجتهدوا على التفتيش عنهما، {ولا تيأسوا من رَوۡح الله}: فإنَّ الرجاء يوجِبُ للعبد السعي والاجتهاد فيما رجاه، والإياس يوجِبُ له التثاقل والتباطؤ، وأولى ما رجا العبادُ فضل الله وإحسانه ورحمته وروحه.","w":"السعدي","en":"That is: Yaqub, peace be upon him, said to his sons: [\"O my sons, go and inquire about Yusuf and his brother\"], that is, be eager and strive to search for them, [\"and do not despair of relief from Allah\"]. For hope obliges the servant to effort and striving in what he hopes for, and despair obliges him to heaviness and slackness; and the most deserving thing for servants to hope for is Allah's bounty, His kindness, His mercy and His relief."},{"bk":"saadi","s":39,"ay":53,"x":"يخبر تعالى عبادَه المسرفينَ بسعةِ كرمِهِ، ويحثُّهم على الإنابة قبل أن لا يمكِنَهم ذلك، فقال:{قل} يا أيُّها الرسولُ ومَنْ قام مقامَه من الدُّعاة لدين الله مخبراً للعبادِ عن ربِّهم: {يا عبادي الذينَ أسۡرَفوا على أنفِسِهم}: باتِّباع ما تَدْعوهم إليه أنفسُهُم من الذُّنوب والسعي في مساخِطِ علاَّم الغُيوب، {لا تَقۡنَطوا من رحمةِ الله}؛ أي: لا تيأسوا منها، فَتُلْقوا بأيديكم إلى التَّهْلُكَه، وتقولوا: قد كَثُرَتْ ذنوبُنا وتراكَمَتْ عيوبُنا؛ فليس لها طريقٌ يزيلُها ولا سبيلٌ يصرِفها فتبقون بسبب ذلك مصرِّين على العصيان، متزوِّدين ما يغضب عليكم الرحمن، ولكن اعرفوا ربَّكم بأسمائِهِ الدالَّةِ على كرمِهِ وجودِهِ، واعلَموا أنَّه يَغْفِرُ الذُّنوبَ جميعاً من الشرك والقتل والزِّنا والربا والظلم وغير ذلك من الذنوب الكبار والصغار.","w":"السعدي","en":"Allah informs His servants who have transgressed against themselves of the vastness of His generosity, and urges them to turn to Him in repentance before that is no longer possible, saying: [\"Say\"], O Messenger, and whoever stands in your place among the callers to Allah's religion, informing the servants from their Lord: [\"O My servants who have transgressed against themselves\"], by following what their selves call them to of sins and by striving in what angers the Knower of the unseen, [\"do not despair of the mercy of Allah\"], that is, do not lose hope in it, casting yourselves into destruction and saying: Our sins have multiplied and our faults have piled up, so there is no way to remove them and no path to turn them away, and so you remain persisting in disobedience, storing up what angers the Most Merciful. But know your Lord by His names that point to His generosity and bounty, and know that He forgives all sins, of associating partners, killing, adultery, usury, injustice and other sins great and small."}],"h":[]},{"id":"tawasaw","ch":"ibtila","t":"«وتواصوا بالصبر وتواصوا بالمرحمة»","e":"وصف أصحاب الميمنة بالتواصي بالصبر والتواصي بالمرحمة.","ay":[[90,17,17],[103,3,3]],"q":[{"bk":"saadi","s":90,"ay":17,"x":"{ثم كان من الذين آمنوا}: وعملوا الصالحات ؛ أي: آمنوا بقلوبهم بما يجب الإيمان به، وعملوا الصالحات بجوارحهم، فدخل في هذا كلُّ قول وفعل واجبٍ أو مستحبٍّ، {وتواصَوۡا بالصَّبۡرِ}: على طاعة الله وعن معصيته وعلى أقداره المؤلمة؛ بأن يحثَّ بعضهم بعضاً على الانقياد لذلك والإتيان به كاملاً منشرحاً به الصَّدر مطمئنَّةً به النفس، {وتواصَوۡا بالمَرۡحَمَةِ}: للخلق؛ من إعطاء محتاجهم، وتعليم جاهلهم، والقيام بما يحتاجون إليه من جميع الوجوه، ومساعدتهم على المصالح الدينيَّة والدنيويَّة، وأن يحبَّ لهم ما يحبُّ لنفسه، ويكره لهم ما يكره لنفسه.","w":"السعدي","en":"[\"Then he was of those who believed\"] and did righteous deeds, that is, they believed with their hearts in what must be believed, and did righteous deeds with their limbs, so every obligatory or recommended word and deed is included; [\"and advised one another to patience\"] in obeying Allah, in refraining from disobeying Him and under His painful decrees, by urging one another to submit to that and carry it out in full, with the chest at ease and the soul at rest; [\"and advised one another to mercy\"] toward creatures, by giving to their needy, teaching their ignorant, attending to what they need in every respect, helping them in their religious and worldly interests, loving for them what he loves for himself and disliking for them what he dislikes for himself."}],"h":[]},{"id":"ikhwa","ch":"takaful","t":"«إنما المؤمنون إخوة»","e":"جعل المؤمنين إخوة وما يترتب على ذلك من الإصلاح والحقوق.","ay":[[49,10,10]],"q":[{"bk":"saadi","s":49,"ay":10,"x":"{إنَّما المؤمنونَ إخوةٌ}: هذا عقدٌ عقدَه الله بين المؤمنين؛ أنَّه إذا وجد من أيِّ شخصٍ كان في مشرق الأرض ومغربها الإيمانُ بالله وملائكته وكتبه ورسله واليوم الآخر؛ فإنَّه أخٌ للمؤمنين أخوَّةً توجبُ أن يحبَّ له المؤمنون ما يحبُّون لأنفسهم، ويكرهوا له ما يكرهون لأنفسهم …","w":"السعدي","en":"[\"The believers are but brothers\"]: this is a bond that Allah tied among the believers: whenever there is found in any person, anywhere in the east or west of the earth, faith in Allah, His angels, His books, His messengers and the Last Day, he is a brother of the believers, with a brotherhood that obliges the believers to love for him what they love for themselves and to dislike for him what they dislike for themselves …"},{"bk":"saadi","s":49,"ay":10,"x":"ولقد أمر اللهُ ورسولُه بالقيام بحقوق المؤمنين بعضهم لبعض وبما يحصُلُ به التآلفُ والتوادُدُ والتواصُلُ بينهم، كل هذا تأييدٌ لحقوق بعضهم على بعض؛ فمن ذلك إذا وقع الاقتتال بينهم الموجب لتفرُّق القلوب وتباغُضها وتدابُرها؛ فَلْيُصْلِح المؤمنون بين إخوانهم، ولْيَسْعَوا فيما به يزول شَنَآنهم.","w":"السعدي","en":"Allah and His Messenger commanded fulfilling the rights of the believers toward one another and what produces affection, love and connection among them. All this supports their rights over one another. Among that, when fighting breaks out among them, which causes hearts to separate and to hate and turn from one another, the believers are to reconcile their brothers and strive in what removes their enmity."}],"h":[]},{"id":"shafaa","ch":"takaful","t":"«من يشفع شفاعة حسنة يكن له نصيب منها»","e":"الشفاعة الحسنة نصيب منها لصاحبها، والتعاون على البر والتقوى.","ay":[[4,85,85]],"q":[{"bk":"saadi","s":4,"ay":85,"x":"المراد بالشفاعة هنا المعاونةُ على أمرٍ من الأمور؛ فمنْ شَفَعَ غيرَهُ وقام معه على أمرٍ من أمور الخير ومنه الشفاعة للمظلومين لمن ظلمهم؛ كان له نصيبٌ من شفاعته بحسب سعيه وعمله ونفعه، ولا ينقُصُ من أجر الأصيل أو المباشر شيءٌ، ومن عاون غيره على أمر من الشرِّ؛ كان عليه كِفْلٌ من الإثم بحسب ما قام به وعاون عليه.","w":"السعدي","en":"What is meant by intercession here is helping with some matter. Whoever intercedes for another and stands with him in some good matter, including interceding for the wronged with the one who wronged them, will have a share of his intercession according to his effort, work and benefit, and nothing is reduced of the reward of the principal or the one who does it directly; and whoever helps another in some evil will bear a portion of the sin according to what he did and helped with."},{"bk":"saadi","s":4,"ay":85,"x":"ففي هذا الحثُّ العظيم على التعاون على البر والتقوى، والزجر العظيم عن التعاون على الإثم والعدوان.","w":"السعدي","en":"In this is a great urging of cooperation in righteousness and taqwa, and a great warning against cooperation in sin and aggression."}],"h":["malhuf"]},{"id":"nasr","ch":"takaful","t":"«وإن استنصروكم في الدين فعليكم النصر»","e":"عقد الولاية بين المؤمنين ووجوب النصر لمن استنصر في الدين.","ay":[[8,72,72]],"q":[{"bk":"saadi","s":8,"ay":72,"x":"{إن استنصروكم في الدين}؛ أي: لأجل قتال من قاتلهم؛ [لأجل دينهم]{فعليكُمُ النصرُ}: والقتال معهم، وأما من قاتلوهم لغير ذلك من المقاصد؛ فليس عليكم نصرهم.","w":"السعدي","en":"[\"If they ask you for help in the religion\"], that is, for fighting those who fight them, on account of their religion, [\"then you must help\"], and fight with them; but as for those they fight for other purposes, you are not obliged to help them."}],"h":["nasr2"]},{"id":"satr","ch":"takaful","t":"صيانة أعراض المؤمنين: «إن الذين يحبون أن تشيع الفاحشة»","e":"النهي عن إشاعة الفاحشة في المؤمنين وعن الغيبة. وعبارة «ستر المسلم» من لفظ الحديث، ولم ترد بنصها في القرآن.","ay":[[24,19,19],[49,12,12]],"q":[{"bk":"saadi","s":24,"ay":19,"x":"وسواء كانت الفاحشةُ صادرةً أو غير صادرةٍ، وكل هذا من رحمة الله لعباده المؤمنين، وصيانة أعراضهم؛ كما صان دماءهم وأموالهم، وأمرهم بما يقتضي المصافاة، وأن يحبَّ أحدُهم لأخيه ما يحبُّ لنفسه، ويكرَهَ له ما يكرَهُ لنفسه.","w":"السعدي","en":"Whether the indecency has occurred or not, all of this is from Allah's mercy to His believing servants and protection of their honour, as He protected their blood and their wealth, and commanded them what leads to sincere friendship, that each of them love for his brother what he loves for himself and dislike for him what he dislikes for himself."},{"bk":"saadi","s":49,"ay":12,"x":"ثم ذَكَرَ مثلاً منفراً عن الغيبة، فقال:{أيحبُّ أحدُكُم أن يأكُلَ لحمَ أخيه مَيۡتاً فكَرِهۡتُموه}: شبَّه أكلَ لحمِهِ ميتاً المكروه للنفوس غايةَ الكراهةِ باغتيابه؛ فكما أنَّكم تكرهون أكل لحمه، خصوصاً إذا كان ميتاً فاقد الروح؛ فكذلك فَلْتَكْرهوا غيبته وأكل لحمه حيًّا، {واتَّقوا اللهَ إنَّ اللهَ توابٌ رحيمٌ}: والتوَّابُ: الذي يأذن بتوبة عبده، فيوفِّقه لها، ثم يتوبُ عليه بقبول توبته، رحيمٌ بعباده؛ حيث دعاهم إلى ما ينفعهم، وقبل منهم التوبة. وفي هذه الآية دليلٌ على التَّحذير الشديد من الغِيبة، وأنَّها من الكبائر؛ لأنَّ الله شبَّهها بأكل لحم الميت، وذلك من الكبائر.","w":"السعدي","en":"Then He gave a parable that makes people recoil from backbiting, saying: [\"Would one of you like to eat the flesh of his dead brother? You would detest it\"]. He likened eating a person's flesh when dead, which souls detest to the utmost, to backbiting him: just as you detest eating his flesh, especially when he is dead and without a soul, so should you detest backbiting him and eating his flesh while he is alive; [\"and fear Allah; indeed Allah is Accepting of repentance, Merciful\"]. The Accepting of repentance is the One who permits His servant to repent, grants him success in it, then accepts his repentance; Merciful to His servants in that He called them to what benefits them and accepted repentance from them. In this verse is strong warning against backbiting and that it is among the major sins, because Allah likened it to eating the flesh of the dead, which is a major sin."}],"h":["akhu"]}],"ay":{"161":"وَلَنَبۡلُوَنَّكُم بِشَيۡءٖ مِّنَ ٱلۡخَوۡفِ وَٱلۡجُوعِ وَنَقۡصٖ مِّنَ ٱلۡأَمۡوَٰلِ وَٱلۡأَنفُسِ وَٱلثَّمَرَٰتِۗ وَبَشِّرِ ٱلصَّٰبِرِينَ","162":"ٱلَّذِينَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةٞ قَالُوٓاْ إِنَّا لِلَّهِ وَإِنَّآ إِلَيۡهِ رَٰجِعُونَ","163":"أُوْلَٰٓئِكَ عَلَيۡهِمۡ صَلَوَٰتٞ مِّن رَّبِّهِمۡ وَرَحۡمَةٞۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُهۡتَدُونَ","183":"۞ لَّيۡسَ ٱلۡبِرَّ أَن تُوَلُّواْ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَلَٰكِنَّ ٱلۡبِرَّ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱلۡمَلَٰٓئِكَةِ وَٱلۡكِتَٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِي ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ إِذَا عَٰهَدُواْۖ وَٱلصَّٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَٰٓئِكَ ٱلَّذِينَ صَدَقُواْۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ","191":"شَهۡرُ رَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ هُدٗى لِّلنَّاسِ وَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡيَصُمۡهُۖ وَمَن كَانَ مَرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ ٱلۡعُسۡرَ وَلِتُكۡمِلُواْ ٱلۡعِدَّةَ وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ وَلَعَلَّكُمۡ تَشۡكُرُونَ","220":"أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَأۡتِكُم مَّثَلُ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِكُمۖ مَّسَّتۡهُمُ ٱلۡبَأۡسَآءُ وَٱلضَّرَّآءُ وَزُلۡزِلُواْ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ مَتَىٰ نَصۡرُ ٱللَّهِۗ أَلَآ إِنَّ نَصۡرَ ٱللَّهِ قَرِيبٞ","225":"۞ يَسۡـَٔلُونَكَ عَنِ ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِۖ قُلۡ فِيهِمَآ إِثۡمٞ كَبِيرٞ وَمَنَٰفِعُ لِلنَّاسِ وَإِثۡمُهُمَآ أَكۡبَرُ مِن نَّفۡعِهِمَاۗ وَيَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلِ ٱلۡعَفۡوَۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ","286":"وَإِن كَانَ ذُو عُسۡرَةٖ فَنَظِرَةٌ إِلَىٰ مَيۡسَرَةٖۚ وَأَن تَصَدَّقُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ","288":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَدَايَنتُم بِدَيۡنٍ إِلَىٰٓ أَجَلٖ مُّسَمّٗى فَٱكۡتُبُوهُۚ وَلۡيَكۡتُب بَّيۡنَكُمۡ كَاتِبُۢ بِٱلۡعَدۡلِۚ وَلَا يَأۡبَ كَاتِبٌ أَن يَكۡتُبَ كَمَا عَلَّمَهُ ٱللَّهُۚ فَلۡيَكۡتُبۡ وَلۡيُمۡلِلِ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبۡخَسۡ مِنۡهُ شَيۡـٔٗاۚ فَإِن كَانَ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ سَفِيهًا أَوۡ ضَعِيفًا أَوۡ لَا يَسۡتَطِيعُ أَن يُمِلَّ هُوَ فَلۡيُمۡلِلۡ وَلِيُّهُۥ بِٱلۡعَدۡلِۚ وَٱسۡتَشۡهِدُواْ شَهِيدَيۡنِ مِن رِّجَالِكُمۡۖ فَإِن لَّمۡ يَكُونَا رَجُلَيۡنِ فَرَجُلٞ وَٱمۡرَأَتَانِ مِمَّن تَرۡضَوۡنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحۡدَىٰهُمَا فَتُذَكِّرَ إِحۡدَىٰهُمَا ٱلۡأُخۡرَىٰۚ وَلَا يَأۡبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُواْۚ وَلَا تَسۡـَٔمُوٓاْ أَن تَكۡتُبُوهُ صَغِيرًا أَوۡ كَبِيرًا إِلَىٰٓ أَجَلِهِۦۚ ذَٰلِكُمۡ أَقۡسَطُ عِندَ ٱللَّهِ وَأَقۡوَمُ لِلشَّهَٰدَةِ وَأَدۡنَىٰٓ أَلَّا تَرۡتَابُوٓاْ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةٗ تُدِيرُونَهَا بَيۡنَكُمۡ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَلَّا تَكۡتُبُوهَاۗ وَأَشۡهِدُوٓاْ إِذَا تَبَايَعۡتُمۡۚ وَلَا يُضَآرَّ كَاتِبٞ وَلَا شَهِيدٞۚ وَإِن تَفۡعَلُواْ فَإِنَّهُۥ فُسُوقُۢ بِكُمۡۗ وَٱتَّقُواْ ٱللَّهَۖ وَيُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ","292":"لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ","478":"۞ لَتُبۡلَوُنَّ فِيٓ أَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ وَلَتَسۡمَعُنَّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَمِنَ ٱلَّذِينَ أَشۡرَكُوٓاْ أَذٗى كَثِيرٗاۚ وَإِن تَصۡبِرُواْ وَتَتَّقُواْ فَإِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ","577":"مَّن يَشۡفَعۡ شَفَٰعَةً حَسَنَةٗ يَكُن لَّهُۥ نَصِيبٞ مِّنۡهَاۖ وَمَن يَشۡفَعۡ شَفَٰعَةٗ سَيِّئَةٗ يَكُن لَّهُۥ كِفۡلٞ مِّنۡهَاۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ مُّقِيتٗا","584":"وَمَا كَانَ لِمُؤۡمِنٍ أَن يَقۡتُلَ مُؤۡمِنًا إِلَّا خَطَـٔٗاۚ وَمَن قَتَلَ مُؤۡمِنًا خَطَـٔٗا فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖ وَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦٓ إِلَّآ أَن يَصَّدَّقُواْۚ فَإِن كَانَ مِن قَوۡمٍ عَدُوّٖ لَّكُمۡ وَهُوَ مُؤۡمِنٞ فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ وَإِن كَانَ مِن قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞ فَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦ وَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ تَوۡبَةٗ مِّنَ ٱللَّهِۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا","757":"لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلۡأَيۡمَٰنَۖ فَكَفَّٰرَتُهُۥٓ إِطۡعَامُ عَشَرَةِ مَسَٰكِينَ مِنۡ أَوۡسَطِ مَا تُطۡعِمُونَ أَهۡلِيكُمۡ أَوۡ كِسۡوَتُهُمۡ أَوۡ تَحۡرِيرُ رَقَبَةٖۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامٖۚ ذَٰلِكَ كَفَّٰرَةُ أَيۡمَٰنِكُمۡ إِذَا حَلَفۡتُمۡۚ وَٱحۡفَظُوٓاْ أَيۡمَٰنَكُمۡۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَشۡكُرُونَ","1231":"إِنَّ ٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَواْ وَّنَصَرُوٓاْ أُوْلَٰٓئِكَ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ وَٱلَّذِينَ ءَامَنُواْ وَلَمۡ يُهَاجِرُواْ مَا لَكُم مِّن وَلَٰيَتِهِم مِّن شَيۡءٍ حَتَّىٰ يُهَاجِرُواْۚ وَإِنِ ٱسۡتَنصَرُوكُمۡ فِي ٱلدِّينِ فَعَلَيۡكُمُ ٱلنَّصۡرُ إِلَّا عَلَىٰ قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ","1294":"۞ إِنَّمَا ٱلصَّدَقَٰتُ لِلۡفُقَرَآءِ وَٱلۡمَسَٰكِينِ وَٱلۡعَٰمِلِينَ عَلَيۡهَا وَٱلۡمُؤَلَّفَةِ قُلُوبُهُمۡ وَفِي ٱلرِّقَابِ وَٱلۡغَٰرِمِينَ وَفِي سَبِيلِ ٱللَّهِ وَٱبۡنِ ٱلسَّبِيلِۖ فَرِيضَةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ","1682":"يَٰبَنِيَّ ٱذۡهَبُواْ فَتَحَسَّسُواْ مِن يُوسُفَ وَأَخِيهِ وَلَا تَاْيۡـَٔسُواْ مِن رَّوۡحِ ٱللَّهِۖ إِنَّهُۥ لَا يَاْيۡـَٔسُ مِن رَّوۡحِ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡكَٰفِرُونَ","2809":"إِنَّ ٱلَّذِينَ يُحِبُّونَ أَن تَشِيعَ ٱلۡفَٰحِشَةُ فِي ٱلَّذِينَ ءَامَنُواْ لَهُمۡ عَذَابٌ أَلِيمٞ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ","2823":"وَلۡيَسۡتَعۡفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغۡنِيَهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱلَّذِينَ يَبۡتَغُونَ ٱلۡكِتَٰبَ مِمَّا مَلَكَتۡ أَيۡمَٰنُكُمۡ فَكَاتِبُوهُمۡ إِنۡ عَلِمۡتُمۡ فِيهِمۡ خَيۡرٗاۖ وَءَاتُوهُم مِّن مَّالِ ٱللَّهِ ٱلَّذِيٓ ءَاتَىٰكُمۡۚ وَلَا تُكۡرِهُواْ فَتَيَٰتِكُمۡ عَلَى ٱلۡبِغَآءِ إِنۡ أَرَدۡنَ تَحَصُّنٗا لِّتَبۡتَغُواْ عَرَضَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَمَن يُكۡرِههُّنَّ فَإِنَّ ٱللَّهَ مِنۢ بَعۡدِ إِكۡرَٰهِهِنَّ غَفُورٞ رَّحِيمٞ","4110":"۞ قُلۡ يَٰعِبَادِيَ ٱلَّذِينَ أَسۡرَفُواْ عَلَىٰٓ أَنفُسِهِمۡ لَا تَقۡنَطُواْ مِن رَّحۡمَةِ ٱللَّهِۚ إِنَّ ٱللَّهَ يَغۡفِرُ ٱلذُّنُوبَ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ","4621":"إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ فَأَصۡلِحُواْ بَيۡنَ أَخَوَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ","4623":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱجۡتَنِبُواْ كَثِيرٗا مِّنَ ٱلظَّنِّ إِنَّ بَعۡضَ ٱلظَّنِّ إِثۡمٞۖ وَلَا تَجَسَّسُواْ وَلَا يَغۡتَب بَّعۡضُكُم بَعۡضًاۚ أَيُحِبُّ أَحَدُكُمۡ أَن يَأۡكُلَ لَحۡمَ أَخِيهِ مَيۡتٗا فَكَرِهۡتُمُوهُۚ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ تَوَّابٞ رَّحِيمٞ","5106":"وَٱلَّذِينَ يُظَٰهِرُونَ مِن نِّسَآئِهِمۡ ثُمَّ يَعُودُونَ لِمَا قَالُواْ فَتَحۡرِيرُ رَقَبَةٖ مِّن قَبۡلِ أَن يَتَمَآسَّاۚ ذَٰلِكُمۡ تُوعَظُونَ بِهِۦۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ","5107":"فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ مِن قَبۡلِ أَن يَتَمَآسَّاۖ فَمَن لَّمۡ يَسۡتَطِعۡ فَإِطۡعَامُ سِتِّينَ مِسۡكِينٗاۚ ذَٰلِكَ لِتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِهِۦۚ وَتِلۡكَ حُدُودُ ٱللَّهِۗ وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمٌ","5223":"لِيُنفِقۡ ذُو سَعَةٖ مِّن سَعَتِهِۦۖ وَمَن قُدِرَ عَلَيۡهِ رِزۡقُهُۥ فَلۡيُنفِقۡ مِمَّآ ءَاتَىٰهُ ٱللَّهُۚ لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا مَآ ءَاتَىٰهَاۚ سَيَجۡعَلُ ٱللَّهُ بَعۡدَ عُسۡرٖ يُسۡرٗا","5355":"إِنَّهُۥ كَانَ لَا يُؤۡمِنُ بِٱللَّهِ ٱلۡعَظِيمِ","5356":"وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ","6033":"فَلَا ٱقۡتَحَمَ ٱلۡعَقَبَةَ","6034":"وَمَآ أَدۡرَىٰكَ مَا ٱلۡعَقَبَةُ","6035":"فَكُّ رَقَبَةٍ","6036":"أَوۡ إِطۡعَٰمٞ فِي يَوۡمٖ ذِي مَسۡغَبَةٖ","6037":"يَتِيمٗا ذَا مَقۡرَبَةٍ","6038":"أَوۡ مِسۡكِينٗا ذَا مَتۡرَبَةٖ","6039":"ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُواْ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ وَتَوَاصَوۡاْ بِٱلۡمَرۡحَمَةِ","6094":"فَإِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرًا","6095":"إِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرٗا","6178":"إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَتَوَاصَوۡاْ بِٱلۡحَقِّ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ","6197":"أَرَءَيۡتَ ٱلَّذِي يُكَذِّبُ بِٱلدِّينِ","6198":"فَذَٰلِكَ ٱلَّذِي يَدُعُّ ٱلۡيَتِيمَ","6199":"وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ"},"h":{"tajir":{"id":"tajir","t":"تاجر يتجاوز عن المعسر","x":"كَانَ تَاجِرٌ يُدَايِنُ النَّاسَ، فَإِذَا رَأَى مُعْسِرًا قَالَ لِفِتْيَانِهِ تَجَاوَزُوا عَنْهُ، لَعَلَّ اللَّهَ أَنْ يَتَجَاوَزَ عَنَّا، فَتَجَاوَزَ اللَّهُ عَنْهُ","b":"bukhari","k":"2078","gr":"صحيح","en":"\"There was a merchant who used to lend to people, and when he saw one in hardship he would say to his servants, 'Overlook his debt, perhaps Allah will overlook ours.' So Allah overlooked his.\""},"sarra":{"id":"sarra","t":"من سرّه أن ينجّيه الله من كرب يوم القيامة","x":"مَنْ سَرَّهُ أَنْ يُنْجِيَهُ اللَّهُ مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ فَلْيُنَفِّسْ عَنْ مُعْسِرٍ أَوْ يَضَعْ عَنْهُ","b":"muslim","k":"1563","gr":"صحيح","en":"\"Whoever would be pleased that Allah save him from the distresses of the Day of Resurrection, let him relieve one in hardship or remit from him.\""},"yassara":{"id":"yassara","t":"من نفّس عن مؤمن كربة","x":"مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ يَسَّرَ اللَّهُ عَلَيْهِ فِي الدُّنْيَا وَالآخِرَةِ وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ فِي الدُّنْيَا وَالآخِرَةِ وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ","b":"muslim","k":"2699","gr":"صحيح","en":"\"Whoever relieves a believer of a distress of this world, Allah will relieve him of a distress of the Day of Resurrection; and whoever eases the way for one in hardship, Allah will ease things for him in this world and the next; and whoever conceals a Muslim, Allah will conceal him in this world and the next; and Allah is in the aid of the servant as long as the servant is in the aid of his brother.\""},"akhdh":{"id":"akhdh","t":"من أخذ أموال الناس يريد أداءها","x":"مَنْ أَخَذَ أَمْوَالَ النَّاسِ يُرِيدُ أَدَاءَهَا أَدَّى اللَّهُ عَنْهُ، وَمَنْ أَخَذَ يُرِيدُ إِتْلاَفَهَا أَتْلَفَهُ اللَّهُ","b":"bukhari","k":"2387","gr":"صحيح","en":"\"Whoever takes people's wealth intending to repay it, Allah will repay it on his behalf; and whoever takes it intending to destroy it, Allah will destroy him.\""},"awla":{"id":"awla","t":"من ترك ديناً فعلى النبي ﷺ قضاؤه","x":"أَنَا أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ، فَمَنْ تُوُفِّيَ مِنَ الْمُؤْمِنِينَ فَتَرَكَ دَيْنًا فَعَلَىَّ قَضَاؤُهُ، وَمَنْ تَرَكَ مَالاً فَلِوَرَثَتِهِ","b":"bukhari","k":"2298","gr":"صحيح","en":"\"I am closer to the believers than their own selves. So whoever of the believers dies leaving a debt, its settlement is upon me; and whoever leaves wealth, it is for his heirs.\""},"itq":{"id":"itq","t":"من أعتق امرأً مسلماً","x":"أَيُّمَا رَجُلٍ أَعْتَقَ امْرَأً مُسْلِمًا اسْتَنْقَذَ اللَّهُ بِكُلِّ عُضْوٍ مِنْهُ عُضْوًا مِنْهُ مِنَ النَّارِ","b":"bukhari","k":"2517","gr":"صحيح","en":"\"Any man who frees a Muslim person, Allah will rescue from the Fire a limb of his for every limb of that person.\""},"ajaba":{"id":"ajaba","t":"أمر المؤمن كله خير","x":"عَجَبًا لأَمْرِ الْمُؤْمِنِ إِنَّ أَمْرَهُ كُلَّهُ خَيْرٌ وَلَيْسَ ذَاكَ لأَحَدٍ إِلاَّ لِلْمُؤْمِنِ إِنْ أَصَابَتْهُ سَرَّاءُ شَكَرَ فَكَانَ خَيْرًا لَهُ وَإِنْ أَصَابَتْهُ ضَرَّاءُ صَبَرَ فَكَانَ خَيْرًا لَهُ","b":"muslim","k":"2999","gr":"صحيح","en":"\"How wonderful is the affair of the believer, for all his affairs are good, and that is for no one except the believer: if good fortune befalls him he is thankful, and that is good for him; and if hardship befalls him he is patient, and that is good for him.\""},"karb":{"id":"karb","t":"دعاء الكرب","x":"لاَ إِلَهَ إِلاَّ اللَّهُ الْعَظِيمُ الْحَلِيمُ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ السَّمَوَاتِ، وَرَبُّ الأَرْضِ، وَرَبُّ الْعَرْشِ الْكَرِيمِ","b":"bukhari","k":"6346","gr":"صحيح","en":"The Messenger of Allah, may Allah bless him and grant him peace, used to say at times of distress: \"There is no god but Allah, the Mighty, the Forbearing; there is no god but Allah, Lord of the Mighty Throne; there is no god but Allah, Lord of the heavens, Lord of the earth and Lord of the Noble Throne.\""},"saee":{"id":"saee","t":"الساعي على الأرملة والمسكين","x":"السَّاعِي عَلَى الأَرْمَلَةِ وَالْمِسْكِينِ كَالْمُجَاهِدِ فِي سَبِيلِ اللَّهِ، أَوِ الْقَائِمِ اللَّيْلَ الصَّائِمِ النَّهَارَ","b":"bukhari","k":"5353","gr":"صحيح","en":"\"The one who strives for the widow and the needy is like the one who fights in the way of Allah, or the one who stands the night in prayer and fasts the day.\""},"malhuf":{"id":"malhuf","t":"إعانة ذي الحاجة الملهوف","x":"عَلَى كُلِّ مُسْلِمٍ صَدَقَةٌ \". قَالُوا فَإِنْ لَمْ يَجِدْ قَالَ \" فَيَعْمَلُ بِيَدَيْهِ فَيَنْفَعُ نَفْسَهُ وَيَتَصَدَّقُ \". قَالُوا فَإِنْ لَمْ يَسْتَطِعْ أَوْ لَمْ يَفْعَلْ قَالَ \" فَيُعِينُ ذَا الْحَاجَةِ الْمَلْهُوفَ \". قَالُوا فَإِنْ لَمْ يَفْعَلْ قَالَ \" فَيَأْمُرُ بِالْخَيْرِ \". أَوْ قَالَ \" بِالْمَعْرُوفِ \". قَالَ فَإِنْ لَمْ يَفْعَلْ قَالَ \" فَيُمْسِكُ عَنِ الشَّرِّ، فَإِنَّهُ لَهُ صَدَقَةٌ","b":"bukhari","k":"6022","gr":"صحيح","en":"\"Every Muslim has to give charity.\" They said: \"And if he does not find anything?\" He said: \"Then let him work with his hands, benefiting himself and giving charity.\" They said: \"And if he is unable or does not do so?\" He said: \"Then let him help the needy one in distress.\" They said: \"And if he does not do so?\" He said: \"Then let him enjoin good\" — or he said: \"what is right.\" He said: \"And if he does not do so?\" He said: \"Then let him refrain from evil, for that is charity for him.\""},"nasr2":{"id":"nasr2","t":"انصر أخاك ظالماً أو مظلوماً","x":"انْصُرْ أَخَاكَ ظَالِمًا أَوْ مَظْلُومًا \". قَالُوا يَا رَسُولَ اللَّهِ هَذَا نَنْصُرُهُ مَظْلُومًا، فَكَيْفَ نَنْصُرُهُ ظَالِمًا قَالَ \" تَأْخُذُ فَوْقَ يَدَيْهِ","b":"bukhari","k":"2444","gr":"صحيح","en":"\"Help your brother, whether he is a wrongdoer or wronged.\" They said: \"O Messenger of Allah, we help him when he is wronged, but how do we help him when he is a wrongdoer?\" He said: \"You take hold of his hands.\""},"akhu":{"id":"akhu","t":"المسلم أخو المسلم: من فرّج كربة ومن ستر مسلماً","x":"الْمُسْلِمُ أَخُو الْمُسْلِمِ، لاَ يَظْلِمُهُ وَلاَ يُسْلِمُهُ، وَمَنْ كَانَ فِي حَاجَةِ أَخِيهِ كَانَ اللَّهُ فِي حَاجَتِهِ، وَمَنْ فَرَّجَ عَنْ مُسْلِمٍ كُرْبَةً فَرَّجَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرُبَاتِ يَوْمِ الْقِيَامَةِ، وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ يَوْمَ الْقِيَامَةِ","b":"bukhari","k":"2442","gr":"صحيح","en":"\"The Muslim is the brother of the Muslim: he does not wrong him and does not abandon him. Whoever is in the need of his brother, Allah is in his need; whoever relieves a Muslim of a distress, Allah will relieve him of a distress of the distresses of the Day of Resurrection; and whoever conceals a Muslim, Allah will conceal him on the Day of Resurrection.\""}},"nay":45,"nq":35,"nh":12};
